/**
 * Max |interpolated value| over the four BS.1770-5 Annex 2 phases for the
 * 12-sample window ending at w[j] (w[j] newest). Fully unrolled; generated
 * from TP_PHASES.
 */
export function interpMax(w: Float32Array, j: number): number {
  const v0 = w[j - 0];
  const v1 = w[j - 1];
  const v2 = w[j - 2];
  const v3 = w[j - 3];
  const v4 = w[j - 4];
  const v5 = w[j - 5];
  const v6 = w[j - 6];
  const v7 = w[j - 7];
  const v8 = w[j - 8];
  const v9 = w[j - 9];
  const v10 = w[j - 10];
  const v11 = w[j - 11];
  let y0 = 0.001708984375 * v0 + 0.010986328125 * v1 + -0.0196533203125 * v2 + 0.033203125 * v3 + -0.0594482421875 * v4 + 0.1373291015625 * v5 + 0.97216796875 * v6 + -0.102294921875 * v7 + 0.047607421875 * v8 + -0.026611328125 * v9 + 0.014892578125 * v10 + -0.00830078125 * v11;
  let y1 = -0.0291748046875 * v0 + 0.029296875 * v1 + -0.0517578125 * v2 + 0.089111328125 * v3 + -0.16650390625 * v4 + 0.465087890625 * v5 + 0.77978515625 * v6 + -0.2003173828125 * v7 + 0.1015625 * v8 + -0.0582275390625 * v9 + 0.0330810546875 * v10 + -0.0189208984375 * v11;
  let y2 = -0.0189208984375 * v0 + 0.0330810546875 * v1 + -0.0582275390625 * v2 + 0.1015625 * v3 + -0.2003173828125 * v4 + 0.77978515625 * v5 + 0.465087890625 * v6 + -0.16650390625 * v7 + 0.089111328125 * v8 + -0.0517578125 * v9 + 0.029296875 * v10 + -0.0291748046875 * v11;
  let y3 = -0.00830078125 * v0 + 0.014892578125 * v1 + -0.026611328125 * v2 + 0.047607421875 * v3 + -0.102294921875 * v4 + 0.97216796875 * v5 + 0.1373291015625 * v6 + -0.0594482421875 * v7 + 0.033203125 * v8 + -0.0196533203125 * v9 + 0.010986328125 * v10 + 0.001708984375 * v11;
  if (y0 < 0) y0 = -y0;
  if (y1 < 0) y1 = -y1;
  if (y2 < 0) y2 = -y2;
  if (y3 < 0) y3 = -y3;
  const a = y0 > y1 ? y0 : y1;
  const b = y2 > y3 ? y2 : y3;
  return a > b ? a : b;
}
